package com.bhojbangla.security;
import java.util.List;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.http.HttpMethod;import org.springframework.security.config.Customizer;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;import org.springframework.web.cors.CorsConfiguration;import org.springframework.web.cors.CorsConfigurationSource;import org.springframework.web.cors.UrlBasedCorsConfigurationSource;
@Configuration public class SecurityConfig{
@Bean SecurityFilterChain chain(HttpSecurity http,JwtFilter filter)throws Exception{return http.csrf(c->c.disable()).cors(Customizer.withDefaults()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/health","/error","/api/auth/**","/api/coverage/**").permitAll().requestMatchers(HttpMethod.POST,"/api/orders").hasRole("CUSTOMER").requestMatchers("/api/admin/**").hasRole("ADMIN").requestMatchers("/api/restaurant/**").hasAnyRole("RESTAURANT","ADMIN").requestMatchers("/api/rider/**").hasAnyRole("RIDER","ADMIN").anyRequest().authenticated()).addFilterBefore(filter,UsernamePasswordAuthenticationFilter.class).build();}
@Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);}
@Bean CorsConfigurationSource cors(@Value("${app.cors.allowed-origins}")String origins){var c=new CorsConfiguration();c.setAllowedOrigins(List.of(origins.split(",")));c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));c.setAllowCredentials(true);var s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}
}
